      receipt.targetArtifact.sourceFile ||
      (selected.target === 'ts'
        ? 'target.ts'
        : selected.target === 'rust'
          ? 'target.rs'
          : selected.target === 'wasm-core'
            ? 'target.wasm.hex'
            : 'target.mjs');
